            await page.get_by_role("button", name="Search").click()
            await page.wait_for_load_state('networkidle')
            await page.get_by_role("link", name="Minerva LumaTech V-Tee").click()
            await page.wait_for_load_state('networkidle')
        except Exception:
            # Fallback: use the first textbox as a filter input and search, then click product
            try:
                await page.get_by_role("textbox").nth(0).fill("Minerva LumaTech V-Tee")
                await page.get_by_role("button", name="Search").click()
                await page.wait_for_load_state('networkidle')
                await page.get_by_role("link", name="Minerva LumaTech V-Tee").click()
                await page.wait_for_load_state('networkidle')
